await pool.query(`create table if not exists operations_audit_logs(
 id uuid primary key,actor_account_id uuid,actor_phone varchar(20),actor_nickname varchar(50),action text not null,resource_type text not null,
 resource_id text,metadata jsonb not null default '{}',created_at timestamptz not null default now()
)`);
await ensureManualGrantSchema(pool);
const writeAudit=async(operator:any,action:string,resourceType:string,resourceId:string|null,metadata:Record<string,unknown>={})=>{await pool.query(`insert into operations_audit_logs(id,actor_account_id,actor_phone,actor_nickname,action,resource_type,resource_id,metadata) values($1,$2,$3,$4,$5,$6,$7,$8)`,[randomUUID(),operator?.accountId||null,operator?.phone||null,operator?.name||operator?.sub||'系统',action,resourceType,resourceId,metadata])};
app.get('/health/ready',async()=>{await pool.query('select 1');return {status:'ready'}});
app.post('/api/auth/login',async(req,reply)=>{const input=z.object({account:z.string().min(1),password:z.string().min(1)}).parse(req.body);let [account]=await rows<any>(`select a.*,coalesce(array_agg(r.role) filter(where r.role is not null),'{}') roles from operations_accounts a left join operations_account_roles r on r.account_id=a.id where a.phone=$1 group by a.id`,[input.account]);if(!account){const configured=authenticateOperationsAccount(operationsAccounts,input.account,input.password);if(!configured)return reply.code(401).send({code:'LOGIN_FAILED',message:'账号或密码不正确'});const id=randomUUID(),salt=randomBytes(16).toString('hex'),hash=passwordDigest(input.password,salt).toString('hex'),client=await pool.connect();try{await client.query('begin');await client.query(`insert into operations_accounts(id,phone,nickname,password_salt,password_hash) values($1,$2,$2,$3,$4) on conflict(phone) do nothing`,[id,configured.account,salt,hash]);await client.query(`insert into operations_account_roles(account_id,role) select id,'SUPER_ADMIN' from operations_accounts where phone=$1 on conflict do nothing`,[configured.account]);await client.query('commit')}catch(error){await client.query('rollback');throw error}finally{client.release()}[account]=await rows<any>(`select a.*,coalesce(array_agg(r.role) filter(where r.role is not null),'{}') roles from operations_accounts a left join operations_account_roles r on r.account_id=a.id where a.phone=$1 group by a.id`,[configured.account])}const actual=passwordDigest(input.password,account.password_salt),expected=Buffer.from(account.password_hash,'hex');if(account.status!=='ACTIVE'||expected.length!==actual.length||!timingSafeEqual(expected,actual))return reply.code(401).send({code:'LOGIN_FAILED',message:'账号或密码不正确'});const token=await new SignJWT({name:account.nickname,phone:account.phone,accountId:account.id,roles:account.roles}).setProtectedHeader({alg:'HS256'}).setSubject(account.phone).setAudience('fresh-operations').setIssuedAt().setExpirationTime('8h').sign(secret);return {data:{token,operator:accountView(account)}}});
app.get('/api/dashboard',async()=>{const [s]=await rows<any>(`select (select count(*) from users) total_users,(select count(*) from users where created_at>=current_date) new_users,(select coalesce(sum(amount_minor),0) from money_orders where status in('PAID','FULFILLING','FULFILLED')) revenue_minor,(select count(*) from money_orders where status='PENDING_PAYMENT') pending_orders,(select count(*) from reconciliation_cases where status='OPEN') open_cases,(select count(*) from reconciliation_cases where status='OPEN' and severity='CRITICAL') critical_cases`);return {data:s}});
app.get('/api/analytics/overview',async(req,reply)=>{if(!requireAnalyticsAccess(req,reply))return;const input=z.object({days:z.coerce.number().int().min(1).max(90).default(7)}).parse(req.query),scope:any={environment:env.OPERATIONS_ANALYTICS_ENV,release:env.OPERATIONS_ANALYTICS_RELEASE,days:input.days,refresh_seconds:60},args=[scope.environment,scope.release,scope.days];const base=`environment=$1 and release=$2 and received_at>=now()-($3::int*interval '1 day')`;const [summary,trend,pageRows,errorRows,eventRows,buildRows]=await Promise.all([rows<any>(`select count(*)::int events,count(*) filter(where event_name='global_page_viewed')::int pv,count(distinct anonymous_id)::int anonymous_uv,count(distinct session_id)::int sessions,count(distinct user_id) filter(where user_id is not null)::int active_users,count(*) filter(where user_id is not null)::int bound_events,max(received_at) last_received_at,round(avg(greatest(0,extract(epoch from(received_at-occurred_at))))::numeric,2) average_delay_seconds from analytics_events where ${base}`,args),rows<any>(`select to_char(date_trunc('day',received_at at time zone 'Asia/Shanghai'),'MM-DD') as day_label,count(*) filter(where event_name='global_page_viewed')::int pv,count(distinct anonymous_id)::int uv,count(distinct session_id)::int sessions from analytics_events where ${base} group by 1 order by 1`,args),rows<any>(`select page_code,coalesce(route,'—') route,count(*) filter(where event_name='global_page_viewed')::int pv,count(distinct anonymous_id)::int uv,count(*) filter(where result='failed' or event_name in('api_request_failed','global_client_error_occurred'))::int errors from analytics_events where ${base} group by page_code,route order by pv desc limit 50`,args),rows<any>(`select coalesce(reason_code,'未分类') reason_code,coalesce(page_code,'未登记页面') page_code,count(*)::int count,count(distinct anonymous_id)::int affected_uv,max(request_id::text) request_id from analytics_events where ${base} and(event_name in('api_request_failed','global_client_error_occurred','user_journey_interrupted') or result in('failed','blocked','timeout')) group by reason_code,page_code order by count desc limit 20`,args),rows<any>(`select event_name,count(*)::int count,count(distinct session_id)::int sessions from analytics_events where ${base} group by event_name order by count desc`,args),rows<any>(`select app_version,commit_sha from analytics_events where environment=$1 and release=$2 order by received_at desc limit 1`,args.slice(0,2))]);const result=summary[0]||{},events=Number(result.events||0);result.binding_rate=events?Number(((Number(result.bound_events||0)/events)*100).toFixed(1)):0;Object.assign(scope,{app_version:buildRows[0]?.app_version||scope.release,commit_sha:buildRows[0]?.commit_sha||null});const eventMap=Object.fromEntries(eventRows.map(x=>[x.event_name,Number(x.count)]));return {data:{scope,summary:result,trend:trend.map(x=>({...x,day:x.day_label})),pageRows:normalizeAnalyticsPageRows(pageRows).slice(0,20),errorRows,eventCounts:eventMap}}});
app.get('/api/analytics/error-diagnostics',async(req,reply)=>{if(!requireAnalyticsAccess(req,reply))return;const input=z.object({days:z.coerce.number().int().min(1).max(90).default(7),pageCode:z.string().max(80).optional(),reasonCode:z.string().max(120).optional()}).parse(req.query),args:any[]=[env.OPERATIONS_ANALYTICS_ENV,env.OPERATIONS_ANALYTICS_RELEASE,input.days],filters=[`environment=$1`,`release=$2`,`received_at>=now()-($3::int*interval '1 day')`,`(event_name in('api_request_failed','global_client_error_occurred','user_journey_interrupted') or result in('failed','blocked','timeout'))`];if(input.pageCode){args.push(input.pageCode);filters.push(`coalesce(page_code,'未登记页面')=$${args.length}`)}if(input.reasonCode){args.push(input.reasonCode);filters.push(`coalesce(reason_code,'未分类')=$${args.length}`)}const where=filters.join(' and '),[summary]=await rows<any>(`select count(*)::int count,count(distinct anonymous_id)::int affected_uv,min(received_at) first_seen_at,max(received_at) last_seen_at from analytics_events where ${where}`,args),groups=await rows<any>(`select coalesce(reason_code,'未分类') reason_code,coalesce(page_code,'未登记页面') page_code,coalesce(max(route),'—') route,count(*)::int count,count(distinct anonymous_id)::int affected_uv,max(received_at) last_seen_at from analytics_events where ${where} group by reason_code,page_code order by count desc limit 20`,args),samples=await rows<any>(`select event_name,result,coalesce(reason_code,'未分类') reason_code,coalesce(page_code,'未登记页面') page_code,coalesce(route,'—') route,source_page,object_type,object_id,app_version,commit_sha,request_id::text,received_at,properties->>'api_template' api_template,properties->>'http_method' http_method,properties->>'http_status' http_status,properties->>'action_code' action_code,device->>'category' device_category,device->>'os' operating_system,device->>'browser' browser,device->>'viewport_group' viewport_group from analytics_events where ${where} order by received_at desc limit 20`,args);return {data:{summary:summary||{count:0,affected_uv:0,first_seen_at:null,last_seen_at:null},groups,samples}}});
app.get('/api/analytics/segments',async(req,reply)=>{if(!requireAnalyticsAccess(req,reply))return;
 const input=z.object({days:z.coerce.number().int().min(1).max(90).default(7)}).parse(req.query),args=[env.OPERATIONS_ANALYTICS_ENV,env.OPERATIONS_ANALYTICS_RELEASE,input.days],base=`e.environment=$1 and e.release=$2 and e.received_at>=now()-($3::int*interval '1 day')`;
 const [products,devices,releases,business]=await Promise.all([
  rows<any>(`with event_products as (
    select e.object_id offering_id,
      count(*) filter(where e.event_name='commerce_offering_viewed')::int views,
      count(*) filter(where e.event_name='commerce_purchase_clicked')::int purchase_clicks
    from analytics_events e where ${base} and e.object_type='offering' group by e.object_id
   ), order_products as (
    select ov.offering_id,max(ov.display_name) display_name,max(o.offering_kind) offering_kind,
      count(*)::int orders,
      count(*) filter(where mo.status in('PAID','FULFILLING','FULFILLED'))::int paid
    from money_orders mo join offering_versions ov on ov.id=mo.offering_version_id join service_offerings o on o.id=ov.offering_id
    where mo.created_at>=now()-($3::int*interval '1 day') group by ov.offering_id
   ) select coalesce(op.display_name,v.display_name,ep.offering_id,'未识别商品') name,
      coalesce(op.offering_kind,o.offering_kind,'UNKNOWN') kind,coalesce(ep.views,0)::int views,coalesce(ep.purchase_clicks,0)::int purchase_clicks,
      coalesce(op.orders,0)::int orders,coalesce(op.paid,0)::int paid
   from event_products ep full join order_products op on op.offering_id::text=ep.offering_id
   left join service_offerings o on o.id::text=coalesce(ep.offering_id,op.offering_id::text)
   left join offering_versions v on v.id=o.current_version_id
   order by paid desc,orders desc,views desc limit 30`,args),
  rows<any>(`select coalesce(e.device->>'category','unknown') category,coalesce(e.device->>'viewport_group','unknown') viewport_group,count(distinct e.anonymous_id)::int uv,count(*)::int events,count(*) filter(where e.result in('failed','blocked','timeout') or e.event_name in('api_request_failed','global_client_error_occurred'))::int errors from analytics_events e where ${base} group by 1,2 order by events desc`,args),
  rows<any>(`select e.app_version,coalesce(e.commit_sha,'未知构建') commit_sha,count(distinct e.session_id)::int sessions,count(*)::int events,count(*) filter(where e.result in('failed','blocked','timeout') or e.event_name in('api_request_failed','global_client_error_occurred'))::int errors from analytics_events e where ${base} group by 1,2 order by events desc limit 20`,args),
  rows<any>(`select (select count(*)::int from users where created_at>=now()-($1::int*interval '1 day')) registered_users,(select count(*)::int from money_orders where created_at>=now()-($1::int*interval '1 day')) orders,(select count(*)::int from money_orders where created_at>=now()-($1::int*interval '1 day') and status in('PAID','FULFILLING','FULFILLED')) paid_orders,(select coalesce(sum(amount_minor),0)::bigint from money_orders where created_at>=now()-($1::int*interval '1 day') and status in('PAID','FULFILLING','FULFILLED')) revenue_minor`,[input.days])
 ]);return {data:{products,devices,releases,business:business[0]||{}}}});
app.get('/api/meta/operation-roles',async()=>({data:operationRoles.map(code=>({code,name:operationRoleCn[code]}))}));
app.get('/api/me',async(req)=>{const operator=(req as any).operator;if(operator.bootstrap)return {data:{phone:null,nickname:operator.name,roles:[{code:'SUPER_ADMIN',name:'超级管理员'}],bootstrap:true}};const [account]=await rows<any>(`select a.*,coalesce(array_agg(r.role) filter(where r.role is not null),'{}') roles from operations_accounts a left join operations_account_roles r on r.account_id=a.id where a.id=$1 group by a.id`,[operator.accountId]);return {data:account?accountView(account):null}});
app.patch('/api/me',async(req,reply)=>{const operator=(req as any).operator;if(operator.bootstrap)return reply.code(409).send({code:'BOOTSTRAP_ACCOUNT_IMMUTABLE',message:'引导管理员请通过服务器安全配置修改资料'});const input=z.object({nickname:z.string().min(2).max(50).optional(),currentPassword:z.string().min(8).optional(),newPassword:z.string().min(8).max(72).optional()}).refine(x=>!x.newPassword||Boolean(x.currentPassword),{message:'修改密码需要输入当前密码'}).parse(req.body);const [account]=await rows<any>('select * from operations_accounts where id=$1',[operator.accountId]);if(!account)return reply.code(404).send({code:'ACCOUNT_NOT_FOUND',message:'运营账号不存在'});if(input.newPassword){const actual=passwordDigest(input.currentPassword!,account.password_salt),expected=Buffer.from(account.password_hash,'hex');if(expected.length!==actual.length||!timingSafeEqual(expected,actual))return reply.code(400).send({code:'PASSWORD_MISMATCH',message:'当前密码不正确'});const salt=randomBytes(16).toString('hex'),hash=passwordDigest(input.newPassword,salt).toString('hex');await pool.query('update operations_accounts set nickname=coalesce($2,nickname),password_salt=$3,password_hash=$4,password_changed_at=now(),updated_at=now() where id=$1',[account.id,input.nickname||null,salt,hash])}else if(input.nickname)await pool.query('update operations_accounts set nickname=$2,updated_at=now() where id=$1',[account.id,input.nickname]);return {data:{updated:true}}});
app.get('/api/accounts',async(req,reply)=>{if(!requireSuperAdmin(req,reply))return;return {data:(await rows<any>(`select a.*,coalesce(array_agg(r.role) filter(where r.role is not null),'{}') roles from operations_accounts a left join operations_account_roles r on r.account_id=a.id group by a.id order by a.created_at desc`)).map(accountView)}});
app.post('/api/accounts',async(req,reply)=>{if(!requireSuperAdmin(req,reply))return;const operator=(req as any).operator,input=z.object({phone:z.string().regex(/^1\d{10}$/),nickname:z.string().min(2).max(50),roles:z.array(z.enum(operationRoles)).min(1)}).parse(req.body);const id=randomUUID(),initialPassword=`Fresh-${randomBytes(5).toString('hex')}`,salt=randomBytes(16).toString('hex'),hash=passwordDigest(initialPassword,salt).toString('hex'),client=await pool.connect();try{await client.query('begin');const created=await client.query<any>('insert into operations_accounts(id,phone,nickname,password_salt,password_hash) values($1,$2,$3,$4,$5) returning *',[id,input.phone,input.nickname,salt,hash]);for(const role of [...new Set(input.roles)])await client.query('insert into operations_account_roles(account_id,role) values($1,$2)',[id,role]);await client.query('commit');await writeAudit(operator,'ACCOUNT_CREATED','OPERATIONS_ACCOUNT',id,{targetPhone:input.phone,targetNickname:input.nickname,roles:input.roles});return reply.code(201).send({data:{account:accountView({...created.rows[0],roles:input.roles}),initialPassword}})}catch(error){await client.query('rollback');if((error as any)?.code==='23505')return reply.code(409).send({code:'PHONE_ALREADY_EXISTS',message:'该手机号已创建运营账号'});throw error}finally{client.release()}});
app.patch('/api/accounts/:id/roles',async(req,reply)=>{if(!requireSuperAdmin(req,reply))return;const operator=(req as any).operator,id=(req.params as any).id,input=z.object({roles:z.array(z.enum(operationRoles)).min(1),status:z.enum(['ACTIVE','DISABLED']).optional()}).parse(req.body),client=await pool.connect();try{await client.query('begin');await client.query('delete from operations_account_roles where account_id=$1',[id]);for(const role of [...new Set(input.roles)])await client.query('insert into operations_account_roles(account_id,role) values($1,$2)',[id,role]);if(input.status)await client.query('update operations_accounts set status=$2,updated_at=now() where id=$1',[id,input.status]);await client.query('commit');await writeAudit(operator,'ACCOUNT_ROLES_UPDATED','OPERATIONS_ACCOUNT',id,{roles:input.roles,status:input.status||'UNCHANGED'});return {data:{updated:true}}}catch(error){await client.query('rollback');throw error}finally{client.release()}});
app.post('/api/accounts/:id/reset-password',async(req,reply)=>{if(!requireSuperAdmin(req,reply))return;const operator=(req as any).operator,id=(req.params as any).id,initialPassword=`Fresh-${randomBytes(5).toString('hex')}`,salt=randomBytes(16).toString('hex'),hash=passwordDigest(initialPassword,salt).toString('hex');const result=await pool.query('update operations_accounts set password_salt=$2,password_hash=$3,password_changed_at=null,updated_at=now() where id=$1 returning id,phone,nickname',[id,salt,hash]);if(!result.rowCount)return reply.code(404).send({code:'ACCOUNT_NOT_FOUND',message:'运营账号不存在'});await writeAudit(operator,'ACCOUNT_PASSWORD_RESET','OPERATIONS_ACCOUNT',id,{targetPhone:result.rows[0].phone,targetNickname:result.rows[0].nickname});return {data:{initialPassword}}});
app.delete('/api/accounts/:id',async(req,reply)=>{if(!requireSuperAdmin(req,reply))return;const operator=(req as any).operator,id=(req.params as any).id;if(id===operator.accountId)return reply.code(409).send({code:'CANNOT_DELETE_SELF',message:'不能删除当前登录账号'});const [account]=await rows<any>(`select a.*,coalesce(array_agg(r.role) filter(where r.role is not null),'{}') roles from operations_accounts a left join operations_account_roles r on r.account_id=a.id where a.id=$1 group by a.id`,[id]);if(!account)return reply.code(404).send({code:'ACCOUNT_NOT_FOUND',message:'运营账号不存在'});if(operationsAccounts.some(x=>x.account===account.phone))return reply.code(409).send({code:'CONFIGURED_ACCOUNT_PROTECTED',message:'系统配置的引导管理员不可删除，可将其停用'});if(account.roles.includes('SUPER_ADMIN')){const [summary]=await rows<any>(`select count(distinct a.id)::int count from operations_accounts a join operations_account_roles r on r.account_id=a.id and r.role='SUPER_ADMIN' where a.status='ACTIVE'`);if(Number(summary.count)<=1)return reply.code(409).send({code:'LAST_SUPER_ADMIN',message:'必须至少保留一位可用的超级管理员'})}await writeAudit(operator,'ACCOUNT_DELETED','OPERATIONS_ACCOUNT',id,{targetPhone:account.phone,targetNickname:account.nickname,roles:account.roles});await pool.query('delete from operations_accounts where id=$1',[id]);return {data:{deleted:true}}});
app.get('/api/users',async(req)=>{const q=String((req.query as any).q||'').trim(),hash=/^1\d{10}$/.test(q)?phoneHash(q):'';const found=await rows<any>(`select u.id,u.status,u.created_at,i.phone_masked,s.display_name_ciphertext,coalesce(sum(g.available_quantity),0)::int seed_balance from users u left join identities i on i.user_id=u.id and i.provider='PHONE' left join lateral(select display_name_ciphertext from subjects where owner_user_id=u.id and type='SELF' and deleted_at is null order by created_at limit 1)s on true left join complimentary_seed_grants g on g.owner_user_id=u.id and g.status='ACTIVE' where ($1='' or i.phone_masked ilike '%'||$1||'%' or i.provider_subject_hash=$2 or u.id::text=$1 or right(replace(u.id::text,'-',''),6)=upper(replace($1,'FRESH-',''))) group by u.id,i.phone_masked,s.display_name_ciphertext order by u.created_at desc limit 100`,[q,hash]);return {data:found.map(x=>({...x,nickname:decrypt(x.display_name_ciphertext)}))}});
app.get('/api/users/:id',async(req)=>{const id=(req.params as any).id;const [user]=await rows<any>(`select u.id,u.status,u.created_at,i.phone_masked,s.display_name_ciphertext from users u left join identities i on i.user_id=u.id and i.provider='PHONE' left join lateral(select display_name_ciphertext from subjects where owner_user_id=u.id and type='SELF' and deleted_at is null order by created_at limit 1)s on true where u.id=$1`,[id]);if(!user)return {data:null};const [orders,seeds,rights,memberships]=await Promise.all([rows('select id,order_number,status,amount_minor,created_at from money_orders where owner_user_id=$1 order by created_at desc',[id]),rows('select id,total_quantity,available_quantity,status,expires_at from complimentary_seed_grants where owner_user_id=$1 order by created_at desc',[id]),rows('select id,service_type,total_quantity,available_quantity,status,expires_at from entitlement_grants where owner_user_id=$1 order by created_at desc',[id]),rows('select id,status,starts_at,ends_at from membership_subscriptions where owner_user_id=$1 order by created_at desc',[id])]);return {data:{...user,nickname:decrypt(user.display_name_ciphertext),orders,seeds,entitlements:rights,memberships}}});
app.get('/api/benefits',async()=>{const found=await rows<any>(`select x.*,i.phone_masked,s.display_name_ciphertext from (
 select '智慧种子' kind,g.id,g.owner_user_id,g.total_quantity,g.available_quantity,g.status,g.expires_at,null::text claim_error from complimentary_seed_grants g
 union all select '服务权益',e.id,e.owner_user_id,e.total_quantity,e.available_quantity,e.status,e.expires_at,null::text claim_error from entitlement_grants e
 union all select '待领取权益',p.id,null::uuid,case when p.payload->>'kind'='SEED' then coalesce((p.payload->>'seedQuantity')::int,0) else 1 end,case when p.payload->>'kind'='SEED' then coalesce((p.payload->>'seedQuantity')::int,0) else 1 end,p.status,null::timestamptz,p.claim_error from operations_pending_benefit_claims p
 )x left join identities i on i.user_id=x.owner_user_id and i.provider='PHONE' left join lateral(select display_name_ciphertext from subjects where owner_user_id=x.owner_user_id and type='SELF' and deleted_at is null order by created_at limit 1)s on true order by x.expires_at desc nulls last limit 200`);return {data:withUserIdentity(found)}});
app.get('/api/benefits/grant-options',async(req,reply)=>{if(!requireBenefitAccess(req,reply))return;const offerings=await rows<any>(`select v.id,o.offering_kind,v.display_name,v.version,v.validity_days from service_offerings o join offering_versions v on v.id=o.current_version_id where v.status='PUBLISHED' order by o.offering_kind,v.display_name`);return {data:{offerings}}});
app.post('/api/benefits/grant-requests',async(req,reply)=>{if(!requireBenefitAccess(req,reply))return;const operator=(req as any).operator,input=z.object({phone:z.string().regex(/^1\d{10}$/),kind:z.enum(['SEED','OFFERING']),seedQuantity:z.number().int().min(1).max(100000).optional(),validityDays:z.number().int().min(1).max(3650).nullable().optional(),offeringVersionId:z.string().uuid().optional(),reason:z.string().min(3).max(500)}).parse(req.body);if(input.kind==='SEED'&&!input.seedQuantity)return reply.code(422).send({code:'SEED_QUANTITY_REQUIRED',message:'请填写智慧种子数量'});if(input.kind==='OFFERING'&&!input.offeringVersionId)return reply.code(422).send({code:'OFFERING_REQUIRED',message:'请选择要赠送的商品'});if(input.offeringVersionId){const [offering]=await rows<any>(`select v.id from offering_versions v where v.id=$1 and v.status='PUBLISHED'`,[input.offeringVersionId]);if(!offering)return reply.code(422).send({code:'OFFERING_NOT_GRANTABLE',message:'请选择已审核发布的商品版本'})}const id=randomUUID(),payload={kind:input.kind,phoneHash:phoneHash(input.phone),phoneMasked:`${input.phone.slice(0,3)}****${input.phone.slice(-4)}`,seedQuantity:input.seedQuantity??null,validityDays:input.validityDays??null,offeringVersionId:input.offeringVersionId??null};const [created]=await rows<any>(`insert into operations_action_requests(id,action_type,status,payload,reason,submitted_by,idempotency_key) values($1,'MANUAL_BENEFIT_GRANT','PENDING',$2,$3,$4,$5) returning *`,[id,payload,input.reason,operator.sub,randomUUID()]);await writeAudit(operator,'MANUAL_BENEFIT_GRANT_REQUESTED','BENEFIT_GRANT',id,{phoneMasked:payload.phoneMasked,kind:payload.kind,offeringVersionId:payload.offeringVersionId,seedQuantity:payload.seedQuantity});return reply.code(201).send({data:created})});
app.get('/api/products',async()=>({data:await rows(`select o.id,o.code,o.offering_kind,o.service_type,o.status offering_status,v.id version_id,v.version,v.status version_status,v.published_at,v.display_name,v.description,v.amount_minor,v.validity_days,v.entitlement_spec,(o.status='ACTIVE' and v.status='PUBLISHED' and v.amount_minor>0) user_visible,
  exists(select 1 from offering_versions history where history.offering_id=o.id and(history.status='PUBLISHED' or history.published_at is not null)) ever_published,
  (select count(*)::int from money_orders mo join offering_versions ordered_version on ordered_version.id=mo.offering_version_id where ordered_version.offering_id=o.id) order_count,
  r.minimum_seed_balance,r.reserved_seed_quantity,r.activity_amount_minor,d.payload draft_payload,d.updated_at draft_updated_at,
  p.id pending_request_id,p.status pending_request_status from service_offerings o left join offering_versions v on v.id=o.current_version_id left join seed_promotion_rules r on r.offering_version_id=v.id and r.status='ACTIVE' left join operations_product_drafts d on d.offering_id=o.id left join lateral(select id,status from operations_action_requests where action_type='PRODUCT_CHANGE' and payload->>'offeringId'=o.id::text and status in('PENDING','FAILED') order by created_at desc limit 1)p on true where o.business_space='SATORI' order by o.created_at desc`)}));
app.post('/api/products',async(req,reply)=>{const operator=(req as any).operator,input=z.object({code:z.string().regex(/^[a-z0-9][a-z0-9-_]{2,63}$/),serviceType:z.string().regex(/^[A-Z0-9_]{2,64}$/),offeringKind:z.enum(['SINGLE','PACKAGE','MEMBERSHIP'])}).and(productDraftSchema).parse(req.body);if(input.offeringKind==='MEMBERSHIP')return reply.code(422).send({code:'MEMBERSHIP_PLAN_CREATION_DISABLED',message:'当前会员计划固定为微光、清和、自在三类。如需调整，请在商品列表中选择对应计划修改内容'});const offeringId=randomUUID(),versionId=randomUUID(),client=await pool.connect();try{await client.query('begin');await client.query(`insert into service_offerings(id,code,business_space,service_type,offering_kind,status) values($1,$2,'SATORI',$3,$4,'DRAFT')`,[offeringId,input.code,input.serviceType,input.offeringKind]);await client.query(`insert into offering_versions(id,offering_id,version,status,display_name,description,amount_minor,entitlement_spec,validity_days,refund_policy_version,refund_policy,terms_version) values($1,$2,1,'DRAFT',$3,$4,$5,$6,$7,'operations-v1','{}','operations-v1')`,[versionId,offeringId,input.displayName,input.description,input.amountMinor,input.entitlementSpec,input.validityDays]);await client.query(`update service_offerings set current_version_id=$2 where id=$1`,[offeringId,versionId]);await client.query(`insert into operations_product_drafts(offering_id,payload,updated_by) values($1,$2,$3)`,[offeringId,input,operator.sub]);await client.query('commit');return reply.code(201).send({data:{id:offeringId}})}catch(error){await client.query('rollback');if((error as any)?.code==='23505')return reply.code(409).send({code:'PRODUCT_CODE_EXISTS',message:'商品编号已存在'});throw error}finally{client.release()}});
app.delete('/api/products/:id',async(req,reply)=>{const operator=(req as any).operator,id=z.string().uuid().parse((req.params as any).id),client=await pool.connect();try{await client.query('begin');const found=await client.query<any>(`select o.id,o.code,o.status,bool_or(v.status='PUBLISHED' or v.published_at is not null) ever_published,(select count(*)::int from money_orders mo join offering_versions ov on ov.id=mo.offering_version_id where ov.offering_id=o.id) order_count,(select count(*)::int from operations_action_requests a where a.payload->>'offeringId'=o.id::text and a.status in('PENDING','FAILED')) pending_count from service_offerings o left join offering_versions v on v.offering_id=o.id where o.id=$1 group by o.id`,[id]),product=found.rows[0];if(!product){await client.query('rollback');return reply.code(404).send({code:'PRODUCT_NOT_FOUND',message:'商品不存在'})}if(product.ever_published||Number(product.order_count)>0||Number(product.pending_count)>0||product.status!=='DRAFT'){await client.query('rollback');return reply.code(409).send({code:'PRODUCT_DELETE_NOT_ALLOWED',message:'只有从未发布、没有订单且没有待审核申请的草稿商品可以删除'})}await client.query(`delete from operations_product_drafts where offering_id=$1`,[id]);await client.query(`update service_offerings set current_version_id=null where id=$1`,[id]);await client.query(`delete from offering_versions where offering_id=$1`,[id]);await client.query(`delete from service_offerings where id=$1`,[id]);await client.query('commit');await writeAudit(operator,'PRODUCT_DRAFT_DELETED','SERVICE_OFFERING',id,{code:product.code});return {data:{deleted:true}}}catch(error){await client.query('rollback');throw error}finally{client.release()}});
app.put('/api/products/:id/draft',async(req,reply)=>{const operator=(req as any).operator,id=(req.params as any).id,input=productDraftSchema.parse(req.body);const result=await pool.query(`insert into operations_product_drafts(offering_id,payload,updated_by,updated_at) select id,$2,$3,now() from service_offerings where id=$1 on conflict(offering_id) do update set payload=excluded.payload,updated_by=excluded.updated_by,updated_at=now() returning offering_id`,[id,input,operator.sub]);if(!result.rowCount)return reply.code(404).send({code:'PRODUCT_NOT_FOUND',message:'商品不存在'});return {data:{saved:true}}});
app.post('/api/products/:id/submit',async(req,reply)=>{const operator=(req as any).operator,id=(req.params as any).id,input=z.object({reason:z.string().min(3).max(300)}).parse(req.body);const [product]=await rows<any>(`select o.id,o.code,o.offering_kind,o.status offering_status,v.display_name,v.description,v.amount_minor,v.validity_days,v.entitlement_spec,d.payload from service_offerings o join operations_product_drafts d on d.offering_id=o.id left join offering_versions v on v.id=o.current_version_id where o.id=$1`,[id]);if(!product)return reply.code(409).send({code:'DRAFT_REQUIRED',message:'请先保存商品草稿'});const draft=productDraftSchema.parse(product.payload);if(draft.offeringStatus==='ACTIVE'&&draft.amountMinor<1)return reply.code(422).send({code:'PRODUCT_PRICE_REQUIRED',message:'用户端可选商品必须填写大于 0 元的标准售价'});if(product.offering_kind==='MEMBERSHIP'&&!/^membership-(glow|serenity|freedom)-/.test(product.code))return reply.code(422).send({code:'MEMBERSHIP_PLAN_CODE_INVALID',message:'当前会员计划固定为微光、清和、自在三类。请返回商品列表，选择对应计划修改价格、权益、有效期等内容'});if(draft.promotion?.enabled&&(draft.promotion.activityAmountMinor<1||draft.promotion.activityAmountMinor>=draft.amountMinor||draft.promotion.reservedSeedQuantity>draft.promotion.minimumSeedBalance))return reply.code(422).send({code:'SEED_PRICE_INVALID',message:'种子解锁价必须大于 0 且低于标准售价，使用种子数不能超过持有门槛'});const entitlementSpec=normalizeEntitlementSpec(draft.entitlementSpec,product.offering_kind),canonicalDraft={...draft,entitlementSpec},changes=draftChanges(product,canonicalDraft);const existing=await rows<any>(`select id from operations_action_requests where action_type='PRODUCT_CHANGE' and status='PENDING' and payload->>'offeringId'=$1 limit 1`,[id]);if(existing.length)return reply.code(409).send({code:'PRODUCT_REVIEW_PENDING',message:'该商品已有待审核申请'});await pool.query(`update operations_product_drafts set payload=$2,updated_by=$3,updated_at=now() where offering_id=$1`,[id,canonicalDraft,operator.sub]);const [created]=await rows<any>(`insert into operations_action_requests(id,action_type,status,payload,reason,submitted_by,idempotency_key) values($1,'PRODUCT_CHANGE','PENDING',$2,$3,$4,$5) returning *`,[randomUUID(),{offeringId:id,code:product.code,offeringKind:product.offering_kind,changes,...canonicalDraft},input.reason,operator.sub,randomUUID()]);await writeAudit(operator,'PRODUCT_REVIEW_SUBMITTED','SERVICE_OFFERING',id,{requestId:created.id,code:product.code,changes});return reply.code(201).send({data:created})});
app.get('/api/products/:id/versions',async(req)=>({data:await rows(`select id,version,status,display_name,amount_minor,validity_days,published_at,created_at from offering_versions where offering_id=$1 order by version desc`,[(req.params as any).id])}));
app.get('/api/orders',async(req)=>{const input=z.object({page:z.coerce.number().int().min(1).default(1),pageSize:z.coerce.number().int().min(1).max(100).default(20),q:z.string().default(''),status:z.string().default('')}).parse(req.query),offset=(input.page-1)*input.pageSize;const found=await rows<any>(`select o.id,o.order_number,o.owner_user_id,o.status,o.amount_minor,o.created_at,v.display_name,coalesce(f.status,'未创建') fulfillment_status,i.phone_masked,s.display_name_ciphertext,count(*) over()::int total_count from money_orders o join offering_versions v on v.id=o.offering_version_id left join lateral(select status from fulfillment_jobs where order_id=o.id order by created_at desc limit 1)f on true left join identities i on i.user_id=o.owner_user_id and i.provider='PHONE' left join lateral(select display_name_ciphertext from subjects where owner_user_id=o.owner_user_id and type='SELF' and deleted_at is null order by created_at limit 1)s on true where ($1='' or o.order_number ilike '%'||$1||'%' or i.phone_masked ilike '%'||$1||'%' or o.request_id::text=$1) and ($2='' or o.status=$2 or coalesce(f.status,'')=$2) order by o.created_at desc limit $3 offset $4`,[input.q.trim(),input.status,input.pageSize,offset]),data=found.map(({total_count,...row})=>row);return {data:withUserIdentity(data),pagination:{page:input.page,pageSize:input.pageSize,total:Number(found[0]?.total_count||0),totalPages:Math.max(1,Math.ceil(Number(found[0]?.total_count||0)/input.pageSize))}}});
app.get('/api/reconciliation',async()=>({data:await rows(`select * from reconciliation_cases order by detected_at desc limit 200`)}));
app.get('/api/audit',async()=>{const [operations,core]=await Promise.all([rows<any>(`select id,action,resource_type,resource_id,metadata,created_at,actor_account_id user_id,case when actor_phone is null then '系统' else left(actor_phone,3)||'****'||right(actor_phone,4) end phone_masked,actor_nickname nickname from operations_audit_logs order by created_at desc limit 300`),rows<any>(`select a.id,a.actor_user_id user_id,a.action,a.resource_type,a.resource_id,a.metadata,a.created_at,i.phone_masked,s.display_name_ciphertext from audit_logs a left join identities i on i.user_id=a.actor_user_id and i.provider='PHONE' left join lateral(select display_name_ciphertext from subjects where owner_user_id=a.actor_user_id and type='SELF' and deleted_at is null order by created_at limit 1)s on true order by a.created_at desc limit 300`)]);const normalized=[...operations.map(x=>({...x,actor:{user_id:x.user_id,phone_masked:x.phone_masked,nickname:x.nickname||'系统'}})),...core.map(x=>({...x,actor:x.user_id?userIdentity(x):{user_id:null,phone_masked:'系统',nickname:'系统'}}))].sort((a,b)=>new Date(b.created_at).getTime()-new Date(a.created_at).getTime()).slice(0,300);return {data:normalized}});
app.get('/api/roles',async()=>({data:await rows(`select r.id,r.user_id,r.role,r.granted_at,i.phone_masked from operator_roles r left join identities i on i.user_id=r.user_id where r.revoked_at is null order by r.granted_at desc`)}));
app.get('/api/action-requests',async()=>({data:await rows(`select * from operations_action_requests order by created_at desc limit 200`)}));
app.post('/api/action-requests',async(req,reply)=>{const operator=(req as any).operator;const input=z.object({actionType:z.enum(['SEED_ADJUSTMENT','ENTITLEMENT_ADJUSTMENT','RECONCILIATION_RESOLVE','PRODUCT_CHANGE']),payload:z.record(z.string(),z.unknown()),reason:z.string().min(3),idempotencyKey:z.string().min(8).optional()}).parse(req.body);const id=randomUUID(),key=input.idempotencyKey||randomUUID();const [created]=await rows(`insert into operations_action_requests(id,action_type,status,payload,reason,submitted_by,idempotency_key) values($1,$2,'PENDING',$3,$4,$5,$6) on conflict(idempotency_key) do update set idempotency_key=excluded.idempotency_key returning *`,[id,input.actionType,input.payload,input.reason,operator.sub,key]);return reply.code(201).send({data:created})});
app.post('/api/action-requests/:id/reject',async(req,reply)=>{const operator=(req as any).operator,input=z.object({note:z.string().min(3)}).parse(req.body),id=(req.params as any).id,[action]=await rows<any>(`select * from operations_action_requests where id=$1`,[id]);if(!action)return reply.code(404).send({code:'NOT_FOUND',message:'申请不存在'});const superAdmin=operator.roles?.includes('SUPER_ADMIN');if(action.submitted_by===operator.sub&&!superAdmin)return reply.code(409).send({code:'FOUR_EYES_REQUIRED',message:'提交人不能审核自己的申请'});const [updated]=await rows<any>(`update operations_action_requests set status='REJECTED',reviewed_by=$2,review_note=$3,reviewed_at=now() where id=$1 and status in('PENDING','FAILED') returning *`,[id,operator.sub,input.note]);if(!updated)return reply.code(409).send({code:'ALREADY_REVIEWED',message:'该申请已经处理'});await writeAudit(operator,'ACTION_REQUEST_REJECTED','ACTION_REQUEST',id,{actionType:action.action_type,note:input.note});return {data:updated}});
app.post('/api/action-requests/:id/approve',async(req,reply)=>{
 const operator=(req as any).operator,input=z.object({note:z.string().min(3)}).parse(req.body),id=(req.params as any).id,client=await pool.connect();
 try{
  await client.query('begin');const found=await client.query<any>(`select * from operations_action_requests where id=$1 for update`,[id]),action=found.rows[0];
  if(!action){await client.query('rollback');return reply.code(404).send({code:'NOT_FOUND',message:'申请不存在'})}
  if(!['PENDING','FAILED'].includes(action.status)){await client.query('rollback');return reply.code(409).send({code:'ALREADY_REVIEWED',message:'该申请已经处理'})}
  if(action.submitted_by===operator.sub&&!operator.roles?.includes('SUPER_ADMIN')){await client.query('rollback');return reply.code(409).send({code:'FOUR_EYES_REQUIRED',message:'提交人不能审核自己的申请'})}
  const p=action.payload as Record<string,unknown>;
  if(action.action_type==='PRODUCT_CHANGE'){
   const offeringId=z.string().uuid().parse(p.offeringId),draft=productDraftSchema.parse(p),lockedResult=await client.query<any>(`select o.*,v.id current_version_id,v.status current_version_status from service_offerings o left join offering_versions v on v.id=o.current_version_id where o.id=$1 for update of o`,[offeringId]),locked=lockedResult.rows[0];
   if(!locked){await client.query('rollback');return reply.code(404).send({code:'PRODUCT_NOT_FOUND',message:'商品不存在'})}
   const versionId=randomUUID(),versionStatus=draft.offeringStatus==='DRAFT'?'DRAFT':'PUBLISHED';
   if(locked.current_version_status==='PUBLISHED'&&versionStatus==='PUBLISHED')await client.query(`update offering_versions set status='RETIRED',effective_to=now() where id=$1`,[locked.current_version_id]);
   await client.query(`insert into offering_versions(id,offering_id,version,status,display_name,description,currency,amount_minor,entitlement_spec,validity_days,purchase_limit,refund_policy_version,refund_policy,terms_version,effective_from,published_at) select $2,$1,coalesce(maximum.version,0)+1,$3::varchar,$4,$5,'CNY',$6,$7,$8,coalesce(v.purchase_limit,'{}'),coalesce(v.refund_policy_version,'operations-v1'),coalesce(v.refund_policy,'{}'),coalesce(v.terms_version,'operations-v1'),case when $3::text='PUBLISHED' then now() end,case when $3::text='PUBLISHED' then now() end from service_offerings o left join offering_versions v on v.id=o.current_version_id cross join lateral(select max(version) version from offering_versions where offering_id=o.id)maximum where o.id=$1 group by maximum.version,v.purchase_limit,v.refund_policy_version,v.refund_policy,v.terms_version`,[offeringId,versionId,versionStatus,draft.displayName,draft.description,draft.amountMinor,draft.entitlementSpec,draft.validityDays]);
   await client.query(`update service_offerings set current_version_id=$2,status=$3,updated_at=now() where id=$1`,[offeringId,versionId,draft.offeringStatus]);
   if(draft.promotion?.enabled)await client.query(`insert into seed_promotion_rules(id,business_space,offering_version_id,rule_version,status,minimum_seed_balance,reserved_seed_quantity,activity_amount_minor,restoration_policy,starts_at,ends_at) values($1,'SATORI',$2,$3,$4,$5,$6,$7,'{}',now(),now()+interval '10 years')`,[randomUUID(),versionId,`operations-${Date.now()}`,draft.offeringStatus==='ACTIVE'?'ACTIVE':'DRAFT',draft.promotion.minimumSeedBalance,draft.promotion.reservedSeedQuantity,draft.promotion.activityAmountMinor]);
   await client.query(`delete from operations_product_drafts where offering_id=$1`,[offeringId]);
   const result={offeringId,versionId,status:draft.offeringStatus};await client.query(`update operations_action_requests set status='EXECUTED',reviewed_by=$2,review_note=$3,reviewed_at=now(),execution_result=$4,executed_at=now() where id=$1`,[id,operator.sub,input.note,result]);await client.query('commit');await writeAudit(operator,'PRODUCT_VERSION_PUBLISHED','SERVICE_OFFERING',offeringId,{requestId:id,versionId,status:draft.offeringStatus});return {data:{...action,status:'EXECUTED',execution_result:result}}
  }
  if(action.action_type==='MANUAL_BENEFIT_GRANT'){
   const result=await executeManualGrant(client,id,p);await client.query(`update operations_action_requests set status='EXECUTED',reviewed_by=$2,review_note=$3,reviewed_at=now(),execution_result=$4,executed_at=now() where id=$1`,[id,operator.sub,input.note,result]);await client.query('commit');await writeAudit(operator,'MANUAL_BENEFIT_GRANTED','BENEFIT_GRANT',id,{phoneMasked:p.phoneMasked,kind:p.kind,result});return {data:{...action,status:'EXECUTED',execution_result:result}}
  }
  if(!env.SATORI_OPERATOR_TOKEN){await client.query('rollback');return reply.code(503).send({code:'OPERATOR_CREDENTIAL_NOT_CONFIGURED',message:'运营执行凭据尚未配置，申请将保留为待审核状态'})}
  await client.query(`update operations_action_requests set status='APPROVED',reviewed_by=$2,review_note=$3,reviewed_at=now() where id=$1`,[id,operator.sub,input.note]);let path='';
  if(action.action_type==='SEED_ADJUSTMENT')path=`/api/v1/operations/commerce/seeds/${p.grantId}/adjustments`;else if(action.action_type==='ENTITLEMENT_ADJUSTMENT')path=`/api/v1/operations/commerce/entitlements/${p.grantId}/adjustments`;else if(action.action_type==='RECONCILIATION_RESOLVE')path=`/api/v1/operations/commerce/reconciliation-cases/${p.caseId}/resolve`;else{await client.query('rollback');return reply.code(422).send({code:'UNSUPPORTED_ACTION',message:'暂不支持该操作'})}
  const response=await fetch(`${env.SATORI_API_BASE}${path}`,{method:'POST',headers:{'content-type':'application/json',authorization:`Bearer ${env.SATORI_OPERATOR_TOKEN}`,'x-request-id':action.idempotency_key},body:JSON.stringify(p)}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(`R1.1 service rejected operation: ${response.status}`);await client.query(`update operations_action_requests set status='EXECUTED',execution_result=$2,executed_at=now() where id=$1`,[id,result]);await client.query('commit');return {data:{...action,status:'EXECUTED',execution_result:result}}
 }catch(error){await client.query('rollback');await pool.query(`update operations_action_requests set status='FAILED',execution_result=$2,executed_at=now() where id=$1`,[id,{message:error instanceof Error?error.message:'执行失败'}]);throw error}finally{client.release()}
});
app.get('/api/meta/status-labels',async()=>({data:stateCn}));
app.setErrorHandler((error,_req,reply)=>{app.log.error(error);const status=(error as any).statusCode&&Number((error as any).statusCode)<500?Number((error as any).statusCode):500;reply.code(status).send({code:(error as any).code||'OPERATIONS_ERROR',message:status<500?String((error as any).message||'请求参数不正确'):'暂时无法完成操作，请稍后重试'})});
await app.listen({port:env.PORT,host:'0.0.0.0'});
